INSERT INTO `mkt_posts` VALUES('1606', '2', '2019-03-19 10:27:45', '2019-03-19 10:27:45', '<h6>Equipamentos para as áreas das engenharias e ciências naturais</h6>		\n					<ul>\n							<li >\n					<a href=\"https://trionica.cloudaccess.host/product/equipamentos-didaticos-e-cientificos/\">					Equipamentos Didáticos e Científicos\n											</a>\n									</li>\n								<li >\n					<a href=\"https://trionica.cloudaccess.host/product/equipamento-de-geofisica/\">					Equipamento de Geofísica \n											</a>\n									</li>\n								<li >\n					<a href=\"https://trionica.cloudaccess.host/product/equipamentos-laboratoriais-2/\">					Equipamentos Laboratoriais \n											</a>\n									</li>\n								<li >\n					<a href=\"https://trionica.cloudaccess.host/product/quadros-interativos/\">					Quadros Interativos \n											</a>\n									</li>\n								<li >\n					<a href=\"https://trionica.cloudaccess.host/product/mobiliario-escolar-e-de-laboratorio/\">					Mobiliário Escolar e de Laboratório \n											</a>\n									</li>\n						</ul>\n			<h6>Equipamentos </h6>		\n		<ul><li>Teoria das Máquinas e Propriedade do Materiais</li><li>Estruturas</li><li>Termodinâmico e Transferência de Calor</li><li>Mecânica de Fluidos e Hidrologia</li><li>Controlo de Processos e Engenharia de Processos</li><li>Tecnologia alimentar</li><li>Tratamento de águas</li><li>Mecânica de fluidos e hidrologia</li><li>Engenharia química e controlo de processos</li><li>Instalações Elétricas</li><li>Energia Elétrica</li><li>Energias Renováveis</li><li>Eletrónica de Potência e Maquinas Electricas</li><li>Circuitos elétricos e Eletrónicos</li><li>Telecomunicações</li><li>Instrumentação</li><li>Automação</li><li>Microprocessadores</li><li>Tecnologia Automóvel</li><li>Física</li><li>Química</li><li>Biologia</li><li>Robótica</li><li>Máquinas CNC e CAD/CAM</li><li>Automação e Controlo</li><li>Mecatronica</li><li>E-Learnig</li><li>Soluções CIM</li><li>Betões</li><li>Asfaltos</li><li>Mecanica de Solos</li></ul>', 'Header', '', 'inherit', 'closed', 'closed', '', '1605-revision-v1', '', '', '2019-03-19 10:27:45', '2019-03-19 10:27:45', '', '1605', 'https://trionica.cloudaccess.host/2019/03/19/1605-revision-v1/', '0', 'revision', '', '0');
